from typing import List

from taf.rfrl.procedures.cloud.setups_teardowns.testing_env import TestingEnv
from taf.rfrl.procedures.resources.python.bts.bts.cloud_bts import CloudBts
from taf.rfrl.procedures.resources.python.bts.components.rmod.cloud_rmod import CloudRmod
from taf.rfrl.procedures.resources.python.bts.utils.exceptions import ResultError


def general_siso_auto_cloud_rmods_reset_during_fail_safe_mode(testing_env: TestingEnv, rmods_names: List[str]):
    """
    Based on:
    QC Test ID: 180643
    QC Test Name: [1.0] CB011039_5G_C_4_Radio_Module_remote_reset_during_fail_safe_mode

    Should report to:
    QC Test ID: 70603
    QC Test Name: General_SiSo_Auto_Cloud_RMODs_Reset_During_Fail_Safe_Mode

    :param testing_env: testing environment prepared for this test case
    :param rmods_names: names of RMODs on which fail-safe mode should be checked;
                        can be taken from "RMOD ID" field of RMOD details in DU WebEM;
                        i.e. ['RMOD-1', 'RMOD-3']
    """
    bts = testing_env.btss[0]
    errors = testing_env.errors

    bts.rmods.check_if_names_exist(names=rmods_names)

    for rmod in bts.rmods:
        if rmod.name in rmods_names:
            try:
                _enable_fail_safe_mode_on_rmod(rmod)
                _reset_rmod_to_enter_fail_safe_mode(rmod)
                _check_if_rmod_entered_fail_safe_mode(rmod)
                _disable_fail_safe_mode_on_rmod(rmod)
                _reset_rmod_to_exit_fail_safe_mode(rmod)
                _check_if_rmod_exited_fail_safe_mode(rmod)
                _check_statuses_of_all_rmods_and_cells(bts)
            except ResultError as exc:
                errors.add_from_exception(exc)

    errors.check()


def teardown_for_general_siso_auto_cloud_rmods_reset_during_fail_safe_mode(testing_env: TestingEnv, rmods_names: List[str]):
    """
    Teardown for this test case, must be used in [Teardown] of Robot Framework test suite.
    :param testing_env: testing environment prepared for this test case
    :param rmods_names: names of RMODs on which fail-safe mode was checked;
                        can be taken from "RMOD ID" field of RMOD details in DU WebEM;
                        i.e. ['RMOD-1', 'RMOD-3']
    """
    bts = testing_env.btss[0]

    for rmod in bts.rmods:
        if rmod.name in rmods_names:
            if rmod.is_in_fail_safe_mode():
                _disable_fail_safe_mode_on_rmod(rmod)
                _reset_rmod_to_exit_fail_safe_mode(rmod)
                _check_if_rmod_exited_fail_safe_mode(rmod)


def _enable_fail_safe_mode_on_rmod(rmod: CloudRmod):
    rmod.enable_fail_safe_mode()


def _reset_rmod_to_enter_fail_safe_mode(rmod: CloudRmod):
    rmod.du.allow_alarm(fault_id='2934',
                        fault_name='Radio Module fail safe mode',
                        unit_path=rmod.runtime_dist_name)
    for cell in rmod.cells:
        rmod.du.cu.allow_alarm(fault_id='7104',
                               fault_name='Matching ServedCell not found over F1-C',
                               unit_path=cell.config_dist_name)
    rmod.reset(timeout=300)


def _check_if_rmod_entered_fail_safe_mode(rmod: CloudRmod):
    if not rmod.is_in_fail_safe_mode():
        rmod.du.disallow_alarm(fault_id='2934',
                               fault_name='Radio Module fail safe mode',
                               unit_path=rmod.runtime_dist_name)
        raise ResultError(f'{rmod.name} did not entered fail-safe mode')

    rmod.du.check_active_alarm(fault_id='2934',
                               fault_name='Radio Module fail safe mode',
                               unit_path=rmod.runtime_dist_name)
    rmod.check_state(state='failed')


def _disable_fail_safe_mode_on_rmod(rmod: CloudRmod):
    rmod.disable_fail_safe_mode()


def _reset_rmod_to_exit_fail_safe_mode(rmod: CloudRmod):
    rmod.reset(timeout=300)


def _check_if_rmod_exited_fail_safe_mode(rmod: CloudRmod):
    rmod.check_state(state='online',
                     timeout=300)
    rmod.du.check_inactive_alarm(fault_id='2934',
                                 fault_name='Radio Module fail safe mode',
                                 unit_path=rmod.runtime_dist_name,
                                 timeout=180)
    rmod.du.disallow_alarm(fault_id='2934',
                           fault_name='Radio Module fail safe mode',
                           unit_path=rmod.runtime_dist_name)

    if rmod.is_in_fail_safe_mode():
        raise ResultError(f'{rmod.name} did not exited fail-safe mode')

    rmod.cells.check_state_on_all(state='online',
                                  timeout=300)

    for cell in rmod.cells:
        rmod.du.cu.disallow_alarm(fault_id='7104',
                                  fault_name='Matching ServedCell not found over F1-C',
                                  unit_path=cell.config_dist_name)


def _check_statuses_of_all_rmods_and_cells(bts: CloudBts):
    bts.rmods.check_state_on_all(state='online')
    bts.cells.check_state_on_all(state='online')
